mapper.update:
update fac_booking set updated_at = now(), status = #{status}, pay_status = coalesce(#{pay}, pay_status), cancel_reason = coalesce(#{reason}, cancel_reason),
    hold_until = case when #{holdMin}::int > 0 then now() + make_interval(mins => #{holdMin}::int) when #{holdMin}::int < 0 then null else hold_until end
    where tenant_id = #{tid} and id = #{id}

mapper.select:
select  from fac_booking b where b.tenant_id = #{tid}
     and b.day >= #{from}::date and b.day <= #{to}::date
     and b.fac_id = #{fac} and b.status = #{status}
     and b.fac_id in #{f}
     and (b.id = #{q} or right(b.sid, 4) = #{q})
    order by b.day, b.start_slot, b.res_id limit 500
